#!/usr/bin/env node
// build-rumors-bundle.mjs — precompile the four NetHack data files
// rumors-loader.js used to readFileSync at runtime into individual
// readable JS modules under js/c2js-runtime/rumors/ + a small
// _index.js.  No source data files needed at runtime.
//
// §23.202 step 1 part B (companion to build-dat-bundle.mjs).
//
// Output layout:
//
//   js/c2js-runtime/rumors/
//     rumors-tru.js           // canonical pre-padded true-rumor lines
//     rumors-fal.js           // canonical pre-padded false-rumor lines
//     engrave.js              // engrave-text lines (default-prepended)
//     epitaph.js              // epitaph-text lines (default-prepended)
//     _index.js               // re-exports RUMORS_BUNDLE
//
// Processing mirrors the previous loadSection: drop '#' / '^' /
// blank lines, padline(line, 60), prepend the per-section default.
//
// Usage:
//   node tools/c2js/build-rumors-bundle.mjs           # build
//   node tools/c2js/build-rumors-bundle.mjs --check   # CI staleness gate

import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __thisFile = fileURLToPath(import.meta.url);
const __thisDir = dirname(__thisFile);
const repoRoot = dirname(dirname(__thisDir));
const DAT_DIR = join(repoRoot, 'nethack-c/upstream/dat');
const OUT_DIR = join(repoRoot, 'js/c2js-runtime/rumors');

const PAD = 60;
function padline(body) {
    if (body.length + 1 >= PAD) return body;
    return body + '_'.repeat(PAD - body.length - 1);
}

function loadSection(filename, defaultContent) {
    const p = join(DAT_DIR, filename);
    if (!existsSync(p)) {
        return defaultContent ? [padline(defaultContent)] : [];
    }
    const src = readFileSync(p, 'utf8');
    const lines = src.split('\n');
    if (lines[lines.length - 1] === '') lines.pop();
    const filtered = lines.filter((l) => l[0] !== '#' && l !== '' && l[0] !== '^');
    const padded = filtered.map(padline);
    if (defaultContent) padded.unshift(padline(defaultContent));
    return padded;
}

// Each section → its own file with `export default <lines-array>`.
const SECTIONS = [
    { name: 'rumors-tru', source: 'rumors.tru', deflt: null,
      bundleKey: 'trueLines',
      header: 'rumors-tru.js — canonical TRUE-rumor lines (oracle, scroll of mail, fortune cookies).' },
    { name: 'rumors-fal', source: 'rumors.fal', deflt: null,
      bundleKey: 'falseLines',
      header: 'rumors-fal.js — canonical FALSE-rumor lines (cursed fortune cookies, hallucinations).' },
    { name: 'engrave', source: 'engrave.txt',
      deflt: 'No matter where you go, there you are.',
      bundleKey: 'engraveLines',
      header: 'engrave.js — random-engraving lines + the makedefs default.' },
    { name: 'epitaph', source: 'epitaph.txt',
      deflt: 'No matter where I went, here I am.',
      bundleKey: 'epitaphLines',
      header: 'epitaph.js — random gravestone epitaph lines + the makedefs default.' },
];

function fileContent(section, lines) {
    return [
        `// ${section.header}`,
        `// AUTO-GENERATED from nethack-c/upstream/dat/${section.source}.`,
        `// Do NOT edit by hand.  Regenerate via tools/c2js/build-rumors-bundle.mjs.`,
        ``,
        `export default ${JSON.stringify(lines)};`,
        ``,
    ].join('\n');
}

function indexContent(stats) {
    const lines = [];
    lines.push('// _index.js — AUTO-GENERATED by tools/c2js/build-rumors-bundle.mjs.');
    lines.push('// Imports the four per-section modules and re-exposes them under');
    lines.push('// the bundle-shape rumors-loader.js consumes (registerRumorsData).');
    lines.push('');
    for (const s of SECTIONS) {
        lines.push(`import ${s.name.replace(/-/g, '_')} from './${s.name}.js';`);
    }
    lines.push('');
    lines.push('export const RUMORS_BUNDLE = {');
    for (const s of SECTIONS) {
        lines.push(`  ${s.bundleKey}: ${s.name.replace(/-/g, '_')},`);
    }
    lines.push('};');
    lines.push('');
    return lines.join('\n');
}

function planFiles() {
    const plan = new Map();
    const stats = {};
    for (const s of SECTIONS) {
        const lines = loadSection(s.source, s.deflt);
        plan.set(`${s.name}.js`, fileContent(s, lines));
        stats[s.name] = lines.length;
    }
    plan.set('_index.js', indexContent(stats));
    return { plan, stats };
}

function listExistingFiles() {
    if (!existsSync(OUT_DIR)) return new Set();
    return new Set(readdirSync(OUT_DIR).filter(f => f.endsWith('.js')));
}

export function runCheck() {
    const { plan, stats } = planFiles();
    const existing = listExistingFiles();
    for (const path of plan.keys()) {
        if (!existing.has(path)) {
            return { ok: false, message: `rumors-bundle: missing ${join('rumors', path)}; run build-rumors-bundle.mjs` };
        }
    }
    for (const f of existing) {
        if (!plan.has(f)) {
            return { ok: false, message: `rumors-bundle: stale extra file ${join('rumors', f)}; run build-rumors-bundle.mjs` };
        }
    }
    for (const [path, content] of plan) {
        const onDisk = readFileSync(join(OUT_DIR, path), 'utf8');
        if (onDisk !== content) {
            return { ok: false, message: `rumors-bundle: stale content in ${join('rumors', path)}; run build-rumors-bundle.mjs` };
        }
    }
    return { ok: true, message: `rumors-bundle: ${plan.size} files up to date (tru=${stats['rumors-tru']} fal=${stats['rumors-fal']} eng=${stats['engrave']} epi=${stats['epitaph']})` };
}

function main() {
    const args = process.argv.slice(2);
    const check = args.includes('--check');
    if (check) {
        const r = runCheck();
        console.error(r.message);
        process.exit(r.ok ? 0 : 1);
    }
    const { plan, stats } = planFiles();
    if (!existsSync(OUT_DIR)) mkdirSync(OUT_DIR, { recursive: true });
    const existing = listExistingFiles();
    for (const f of existing) {
        if (!plan.has(f)) rmSync(join(OUT_DIR, f));
    }
    let bytes = 0;
    for (const [path, content] of plan) {
        writeFileSync(join(OUT_DIR, path), content);
        bytes += content.length;
    }
    console.log(`wrote ${plan.size} files to ${OUT_DIR}/`);
    console.log(`  tru: ${stats['rumors-tru']} lines`);
    console.log(`  fal: ${stats['rumors-fal']} lines`);
    console.log(`  eng: ${stats['engrave']} lines`);
    console.log(`  epi: ${stats['epitaph']} lines`);
    console.log(`  total bytes: ${bytes}`);
}

if (import.meta.url === `file://${process.argv[1]}`) {
    main();
}
